/**
 * Kumva Trigger Node
 * Initiates campaign by fetching and triggering flows for each contact
 */

module.exports = function(RED) {
  const { v4: uuidv4 } = require('uuid');
  const csv = require('csvtojson');
  const helpers = require('kumva-insights/utils/helpers');
  const DataStorage = require('kumva-insights/utils/data-storage');

  function KumvaTriggerNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    // Initialize data storage
    const storage = new DataStorage();

    // Campaign state
    let campaignId = uuidv4();
    let contacts = [];
    let currentIndex = 0;
    let triggerInterval = null;
    let campaignRunning = false;

    /**
     * Parse contacts from different sources
     */
    async function parseContacts() {
      try {
        const source = config.contactSource;
        contacts = [];

        switch(source) {
          case 'csv':
            contacts = await parseCSV(config.csvData);
            break;

          case 'json':
            contacts = helpers.safeJsonParse(config.jsonData, []);
            if (!Array.isArray(contacts)) {
              contacts = [];
            }
            break;

          case 'manual':
            contacts = config.manualContacts
              .split('\n')
              .map(phone => phone.trim())
              .filter(phone => phone)
              .map(phone => ({
                [config.phoneColumn]: phone
              }));
            break;

          default:
            node.warn(`Unknown contact source: ${source}`);
            return false;
        }

        // Validate and clean contacts
        contacts = contacts.filter(contact => {
          const phone = contact[config.phoneColumn];
          return phone && helpers.isValidPhoneNumber(phone);
        });

        return contacts.length > 0;
      } catch (error) {
        node.error(`Error parsing contacts: ${error.message}`);
        return false;
      }
    }

    /**
     * Parse CSV data
     */
    async function parseCSV(csvData) {
      try {
        if (!csvData || csvData.trim() === '') {
          return [];
        }

        // Use csvtojson for robust parsing
        const result = await csv().fromString(csvData);
        return result;
      } catch (error) {
        node.warn(`CSV parsing error: ${error.message}`);
        // Fallback to simple parsing
        return helpers.parseSimpleCSV(csvData);
      }
    }

    /**
     * Process next contact
     */
    function processNextContact() {
      if (currentIndex >= contacts.length) {
        completeCampaign();
        return;
      }

      const contact = contacts[currentIndex];
      currentIndex++;

      // Resolve variables in initial message
      const initialMessage = helpers.resolveVariables(
        config.initialMessage,
        contact
      );

      // Create message for the flow
      const msg = {
        phoneNumber: contact[config.phoneColumn],
        contactData: contact,
        campaignId: campaignId,
        initialMessage: initialMessage,
        _kumva: {
          campaignId: campaignId,
          contactIndex: currentIndex - 1,
          totalContacts: contacts.length
        }
      };

      // Additional fields as direct message properties
      if (config.additionalFields) {
        const fields = config.additionalFields.split(',').map(f => f.trim());
        fields.forEach(field => {
          if (contact[field] !== undefined) {
            msg[field] = contact[field];
          }
        });
      }

      node.send(msg);
      node.status({
        fill: 'blue',
        shape: 'dot',
        text: `Processing ${currentIndex}/${contacts.length}`
      });
    }

    /**
     * Complete campaign
     */
    function completeCampaign() {
      if (triggerInterval) {
        clearInterval(triggerInterval);
        triggerInterval = null;
      }

      campaignRunning = false;

      // Save campaign metadata
      storage.saveCampaign(campaignId, {
        name: config.name,
        contactSource: config.contactSource,
        totalContacts: contacts.length,
        completedAt: new Date().toISOString(),
        status: 'completed'
      });

      node.status({
        fill: 'green',
        shape: 'dot',
        text: `Campaign complete (${contacts.length} contacts)`
      });

      node.log(`Campaign ${campaignId} completed with ${contacts.length} contacts`);
    }

    /**
     * Start the campaign
     */
    async function startCampaign() {
      try {
        if (campaignRunning) {
          node.warn('Campaign already running');
          return;
        }

        // Parse contacts
        const parsed = await parseContacts();
        if (!parsed) {
          node.error('No valid contacts found');
          node.status({
            fill: 'red',
            shape: 'dot',
            text: 'No valid contacts'
          });
          return;
        }

        campaignRunning = true;
        currentIndex = 0;

        // Save campaign metadata
        storage.saveCampaign(campaignId, {
          name: config.name,
          contactSource: config.contactSource,
          totalContacts: contacts.length,
          startedAt: new Date().toISOString(),
          status: 'running'
        });

        node.status({
          fill: 'blue',
          shape: 'dot',
          text: `Starting campaign (${contacts.length} contacts)`
        });

        // Calculate interval based on rate limit
        // rateLimit is contacts per minute, convert to milliseconds between contacts
        const rateLimit = config.rateLimit || 60;
        const intervalMs = (60000 / rateLimit);

        // Process contacts with rate limiting
        triggerInterval = setInterval(() => {
          processNextContact();
        }, intervalMs);

        // Process first contact immediately
        processNextContact();

      } catch (error) {
        node.error(`Campaign error: ${error.message}`);
        node.status({
          fill: 'red',
          shape: 'dot',
          text: 'Error'
        });
      }
    }

    /**
     * Handle incoming messages
     */
    node.on('input', function(msg) {
      // Trigger node can be started manually via input
      if (msg.payload === 'start' || msg.trigger === true) {
        startCampaign();
      } else if (msg.payload === 'stop' || msg.trigger === false) {
        if (triggerInterval) {
          clearInterval(triggerInterval);
          triggerInterval = null;
        }
        campaignRunning = false;
        node.status({
          fill: 'orange',
          shape: 'dot',
          text: 'Stopped'
        });
      }
    });

    /**
     * Auto-start campaign on deploy
     */
    node.on('deploy', function() {
      // Don't auto-start on deploy - require manual trigger
      node.status({
        fill: 'yellow',
        shape: 'ring',
        text: 'Ready to trigger'
      });
    });

    /**
     * Cleanup on close
     */
    node.on('close', function() {
      if (triggerInterval) {
        clearInterval(triggerInterval);
      }
      campaignRunning = false;
    });

    // Initialize status
    node.status({
      fill: 'yellow',
      shape: 'ring',
      text: 'Ready to trigger'
    });
  }

  RED.nodes.registerType('kumva-trigger', KumvaTriggerNode);
};